<template><view class="page"><AppTopbar :title="active?active.nickname:'聊天'"/><view v-if="!active" class="list"><view v-for="item in sessions" :key="item.id" class="session" @tap="openSession(item)"><UserAvatar :name="item.nickname"/><view class="main"><view class="head"><text>{{item.nickname}}</text><text class="time">{{item.time}}</text></view><text class="preview">{{item.preview}}</text></view><text v-if="item.unread" class="unread">{{item.unread}}</text></view></view><view v-else class="conversation"><scroll-view scroll-y class="messages"><view v-for="(item,i) in active.messages" :key="i" :class="['message',item.mine?'mine':'']"><text>{{item.text}}</text></view></scroll-view><view class="composer"><input v-model="draft" placeholder="说点什么" confirm-type="send" @confirm="send"/><button @tap="send">发送</button></view></view></view></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppTopbar from '../../components/AppTopbar.vue';import UserAvatar from '../../components/UserAvatar.vue';import {requireLogin} from '../../utils/auth';const sessions=ref([{id:1,nickname:'小林同学',preview:'周六体育馆见？',time:'昨天',unread:1}]);const active=ref(null);const draft=ref('');onShow(()=>requireLogin());function openSession(item){active.value={nickname:item.nickname,messages:[{mine:false,text:'你好，看到你的标签了！'},{mine:true,text:'你好，周末一起练球吗？'},{mine:false,text:'周六体育馆见？'}]}}function send(){const text=draft.value.trim();if(!text||!active.value)return;active.value.messages.push({mine:true,text});draft.value=''}
</script>
<style scoped>.page{min-height:100vh}.session{display:flex;align-items:center;padding:28rpx 32rpx;background:#fff;border-bottom:1rpx solid #eee}.main{flex:1;margin-left:22rpx}.head{display:flex;justify-content:space-between}.time,.preview{color:#999;font-size:23rpx}.preview{display:block;margin-top:10rpx}.unread{width:34rpx;height:34rpx;border-radius:50%;line-height:34rpx;text-align:center;color:#fff;background:#fa5151;font-size:20rpx}.messages{height:calc(100vh - 250rpx);padding:24rpx 28rpx;box-sizing:border-box}.message{margin:14rpx 0;display:flex}.message text{max-width:70%;padding:18rpx 22rpx;background:#fff;border-radius:8rpx}.mine{justify-content:flex-end}.mine text{background:#95ec69}.composer{position:fixed;bottom:0;left:0;right:0;display:flex;padding:16rpx 20rpx;background:#f7f7f7}.composer input{flex:1;height:76rpx;padding:0 20rpx;background:#fff;border-radius:8rpx}.composer button{width:130rpx;height:76rpx;line-height:76rpx;margin-left:16rpx;color:#fff;background:#07c160}</style>
